package com.smart.ecommerce.repository;
import com.smart.ecommerce.entity.User;import com.smart.ecommerce.enums.Role;import com.smart.ecommerce.enums.UserStatus;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.domain.Page;import org.springframework.data.repository.query.Param;
public interface UserRepository extends JpaRepository<User,Long>, JpaSpecificationExecutor<User>{ Optional<User> findByEmail(String email); boolean existsByEmail(String email); boolean existsByPhoneNumber(String phoneNumber); long countByRoleAndStatus(Role role, UserStatus status); @Query("select u from User u where (:q is null or lower(concat(u.firstName,' ',u.lastName,' ',u.email,' ',u.phoneNumber)) like lower(concat('%',:q,'%'))) and (:role is null or u.role=:role) and (:status is null or u.status=:status)") Page<User> search(@Param("q") String q,@Param("role") Role role,@Param("status") UserStatus status, org.springframework.data.domain.Pageable pageable); }
